from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        best_gain = 0

        for target in range(1, 51):
            if target == k:
                continue

            current = 0
            best_for_target = 0

            for num in nums:
                if num == target:
                    current += 1
                elif num == k:
                    current -= 1

                if current < 0:
                    current = 0

                best_for_target = max(best_for_target, current)

            best_gain = max(best_gain, best_for_target)

        return base + best_gain
